async function loadContractHistory(){const now=Date.now()/1000;for(const [a,m] of Object.entries(state?state.markets:{})){const h=contractHist[a];if(!m||!m.ticker||m.status!=='active'||(h&&h.ticker===m.ticker&&now-h.at<60))continue;try{const r=await fetch('/api/contract_history?asset='+encodeURIComponent(a)+'&ticker='+encodeURIComponent(m.ticker)),d=await r.json();contractHist[a]={ticker:m.ticker,minutes:r.ok?d.minutes:[],error:r.ok?null:d.error,at:now};if(r.ok&&d.trades)addTrades(m.ticker,d.trades)}catch{}}setTimeout(loadContractHistory,5000)}
