 const values=s.curve.map(x=>x.value),lo=Math.min(...values)-5,hi=Math.max(...values)+5,points=values.length>1?values:[values[0],values[0]],coords=points.map((v,i)=>[(i/(points.length-1))*700,180-(v-lo)/(hi-lo)*170]),path=coords.map(([x,y],i)=>(i?'L':'M')+x+','+y).join(' ');$('#line').setAttribute('d',path);$('#area').setAttribute('d',path+' L700,190 L0,190 Z');$('#axis-top').textContent=money(hi);$('#axis-mid').textContent=money((hi+lo)/2);$('#axis-low').textContent=money(lo);$('#chart-value').textContent=money(values.at(-1));const pc=all.filter(t=>(t.mode||'paper')==='paper').length;$('#chart-note').textContent=pc?pc+' closed paper trades':'Your first closed paper trade will start the curve';
