function clock(){if(!state)return;const down=Date.now()-lastSuccess>10000;$('#feed-pill').textContent=down?'● Disconnected':(Object.keys(state.errors||{}).length?'● Feed partly unavailable':'● Market data connected');document.querySelectorAll('.mcard').forEach(card=>{const m=state.markets[card.dataset.asset],sec=m?Math.max(0,Math.floor(m.close-Date.now()/1000)):null;card.querySelector('.mc-countdown').textContent=sec==null?'—:—':mmss(sec)})}
async function refresh(){try{const r=await fetch('/api/state');if(!r.ok)throw Error();const s=await r.json();lastSuccess=Date.now();render(s)}catch{$('#status-notice').textContent='Local server is unreachable. Displayed values may be stale.';$('#feed-pill').textContent='● Disconnected'}}
async function loadPrices(){const assets=state?[...new Set([...state.config.assets,...Object.keys(state.positions)])].filter(a=>CHARTABLE.includes(a)):[];for(const a of assets){try{const r=await fetch('/api/price?asset='+encodeURIComponent(a)),d=await r.json();if(!r.ok)priceErrors[a]=d.error||'Price feed unavailable';else{prices[a]=d;delete priceErrors[a]}}catch{priceErrors[a]='Local server unreachable'}drawChart(a)}setTimeout(loadPrices,10000)}
async function loadTicks(){try{const r=await fetch('/api/ticks?after='+lastTick);if(r.ok){const d=await r.json();for(const [a,pts] of Object.entries(d.ticks)){if(!pts.length)continue;const buf=ticks[a]||(ticks[a]=[]);for(const p of pts)if(!buf.length||p[0]>buf.at(-1)[0])buf.push(p);if(buf.length>1200)buf.splice(0,buf.length-1200);lastTick=Math.max(lastTick,buf.at(-1)[0]-5)}for(const a of CHARTABLE){if(d.errors[a])tickErrors[a]=d.errors[a];else delete tickErrors[a]}document.querySelectorAll('.mcard').forEach(c=>{if(views[c.dataset.asset]==='1s')drawChart(c.dataset.asset)})}}catch{}setTimeout(loadTicks,1000)}
async function poll(){await refresh();setTimeout(poll,1000)}
poll().then(()=>{loadPrices();loadTicks();loadContracts();loadContractHistory();loadIndex()});setInterval(clock,1000);
